                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rts_tat as WITH base AS ( SELECT sku_group, vendor_name, CASE WHEN UPPER( TRIM( REGEXP_REPLACE( REGEXP_REPLACE( REGEXP_REPLACE(vendor_name, \'[\\r\\n\\t]+\', \' \'), \'\\s+\', \' \' ), \'\\s*-\\s*[^-]+$\', \'\' ) ) ) IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'KESAVAM CLOTHING PRIVATE LIMITED\', \'ADITYA INTERNATIONAL\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'GS CLOTHING\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'SUBHASH POLYTEX LIMITED\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BBI\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\', \'SILVER SPARK APPAREL LIMITED\' ) THEN \'south\' ELSE NULL END AS vendor_region, CASE WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'A ONE KNITWEARS \', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'delhi\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'SUBHASH POLYTEX LIMITED\',\'ADITYA INTERNATIONAL\',\'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\',\'GOOD GOOD WEARS\',\'MAITRI KNITWEAR\',\'MANGLAM COLORS PRIVATE LIMITED\',\'MINERVA FASHION PVT LTD\',\'NEW MIGLANI HOSIERY FACTORY\',\'OBERAI KNITWEAR\',\'SHIVAAY KNITWEAR\',\'SHREE KRISHNA ENTERPRISES\',\'GS CLOTHING\',\'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\' ) THEN \'ludhiana\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BBI\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'SAI TEXTILES SHADEZ\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'CHECK MATE\', \'ETTRO\', \'GROOVY FASHIONS\', \'RAUNAK TEXTILES\', \'VISHNU TRADING CO.\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\', \'SILVER SPARK APPAREL LIMITED\' ) THEN \'bangalore\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'KESAVAM CLOTHING PRIVATE LIMITED\' ) THEN \'kolkata\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'PADMA SHRI KNIT WEAR\',\'VP KNIT FASHIONS\',\'INDIANA PUNTOS CLOTHING\',\'ASIAN CLOTHINGS\',\'VANITHA GARMENTS\',\'WEAREVER\',\'S R APPARELS\' ) THEN \'tirrupur\' WHEN UPPER(TRIM(REGEXP_REPLACE(vendor_name, \'\\s*-\\s*[^-]+$\', \'\'))) IN ( \'ADDON CLOTHING\',\'CHILLCARE APPARELS PRIVATE LIMITED\',\'LAMSOLEE CLOTHING COMPANY\',\'RENAISSANCE FASHIONS\',\'SAANVI TRADERS\', \'VISTA GLOBAL COMPANY\' ) THEN \'mumbai\' ELSE NULL END AS vendor_location, south_po, north_po, south_qty, north_qty, inspection_date FROM snitch_db.maplemonk.pre_final_rts_automation ), ALLOCATED AS ( SELECT SKU_GROUP, MAX( CASE WHEN WAREHOUSE = \'TAURU\' THEN PLANNED_DATE END ) AS planned_date_north, MAX( CASE WHEN WAREHOUSE = \'YLKWH\' THEN PLANNED_DATE END ) AS planned_date_south, MAX( CASE WHEN WAREHOUSE = \'TAURU\' THEN ACTUAL_DELIVERED_DATE END ) AS actual_delivered_date_north, MAX( CASE WHEN WAREHOUSE = \'YLKWH\' THEN ACTUAL_DELIVERED_DATE END ) AS actual_delivered_date_south FROM ( SELECT SKU_GROUP, PLANNED_DATE, ACTUAL_DELIVERED_DATE, WAREHOUSE, ROW_NUMBER() OVER ( PARTITION BY SKU_GROUP, WAREHOUSE ORDER BY PLANNED_DATE DESC ) AS rn FROM SNITCH_DB.MAPLEMONK.DAILY_INWARD_AND_OPERATION_REPORT WHERE WAREHOUSE IN (\'TAURU\', \'YLKWH\') ) a WHERE rn = 1 GROUP BY SKU_GROUP ), planned_month as ( SELECT cleaned_sku, CASE WHEN SUM(CASE WHEN remarks_final ILIKE \'April%\' THEN 1 ELSE 0 END) > 0 AND SUM(CASE WHEN remarks_final ILIKE \'May%\' THEN 1 ELSE 0 END) > 0 THEN \'APRIL-MAY\' WHEN SUM(CASE WHEN remarks_final ILIKE \'April%\' THEN 1 ELSE 0 END) > 0 THEN \'APRIL\' WHEN SUM(CASE WHEN remarks_final ILIKE \'May%\' THEN 1 ELSE 0 END) > 0 THEN \'MAY\' ELSE NULL END AS planned_month FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks GROUP BY cleaned_sku ), po_dates AS ( SELECT TRIM(UPPER(lot_number)) AS lot_number, MAX( COALESCE( TRY_TO_DATE(TO_VARCHAR(order_date), \'YYYY-MM-DD\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'D/M/YYYY\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'D-M-YYYY\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'DD-MON-YYYY\'), TRY_TO_DATE(TO_VARCHAR(order_date), \'DD-MON-YY\') ) ) AS order_date FROM snitch_db.maplemonk.logic_purchase_order WHERE lot_number IS NOT NULL GROUP BY 1 ), po_ranked AS ( SELECT b.sku_group, b.south_po, b.north_po, b.inspection_date, sp.order_date AS south_po_date, np.order_date AS north_po_date, ROW_NUMBER() OVER ( PARTITION BY b.sku_group ORDER BY sp.order_date DESC NULLS LAST ) AS south_po_rn, ROW_NUMBER() OVER ( PARTITION BY b.sku_group ORDER BY np.order_date DESC NULLS LAST ) AS north_po_rn FROM base b LEFT JOIN po_dates sp ON TRIM(UPPER(b.south_po)) = sp.lot_number AND sp.order_date <= b.inspection_date LEFT JOIN po_dates np ON TRIM(UPPER(b.north_po)) = np.lot_number AND np.order_date <= b.inspection_date ), grn_issues AS ( WITH cleaned AS ( SELECT REGEXP_REPLACE( UPPER(TRIM(sku::STRING)), \'^[0-9]+[-–—]\', \'\' ) AS clean_sku, sku, warehouse_name, bill_date, issue FROM snitch_db.maplemonk.grn_issues_joined ), normalized AS ( SELECT CASE WHEN clean_sku LIKE \'SN%\' OR clean_sku LIKE \'BP%\' THEN clean_sku WHEN clean_sku LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(clean_sku, \'^[^-]+-[^-]+\'))) WHEN clean_sku LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(clean_sku, \'^[^-]+-[^-]+-[^-]+\'))) WHEN clean_sku LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(clean_sku, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN clean_sku LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(clean_sku, \'^[^-]+-[^-]+\'))) ELSE clean_sku END END AS raw_sku_group, warehouse_name, bill_date, issue FROM cleaned ) SELECT CASE WHEN REGEXP_LIKE(raw_sku_group, \'.*-[0-9]$\') THEN REGEXP_REPLACE(raw_sku_group, \'-([0-9])$\', \'-0\\1\') ELSE raw_sku_group END AS sku_group, warehouse_name, bill_date, issue FROM normalized ) SELECT b.sku_group, b.vendor_name, b.vendor_region, b.vendor_location, CASE b.vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END AS expected_tat_north, CASE b.vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END AS expected_tat_south, pr.south_po, pr.north_po, pr.south_po_date, pr.north_po_date, CASE WHEN COALESCE(TRY_TO_NUMBER(b.south_qty), 0) > 0 THEN b.inspection_date END AS south_inspection_date, CASE WHEN COALESCE(TRY_TO_NUMBER(b.north_qty), 0) > 0 THEN b.inspection_date END AS north_inspection_date, a.planned_date_south as south_allocation, a.planned_date_north as north_allocation, a.actual_delivered_date_north as north_delivered, a.actual_delivered_date_south as south_delivered, DATEDIFF( day, a.planned_date_south, a.actual_delivered_date_south ) AS south_actual_tat, DATEDIFF( day, a.planned_date_north, a.actual_delivered_date_north ) AS north_actual_tat, CASE WHEN DATEDIFF(day, a.planned_date_north, a.actual_delivered_date_north) IS NOT NULL THEN DATEDIFF(day, a.planned_date_north, a.actual_delivered_date_north) - CASE b.vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END END AS north_tat_deviation, CASE WHEN DATEDIFF(day, a.planned_date_south, a.actual_delivered_date_south) IS NOT NULL THEN DATEDIFF(day, a.planned_date_south, a.actual_delivered_date_south) - CASE b.vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END END AS south_tat_deviation, pm.planned_month , LISTAGG(DISTINCT CASE WHEN gi.warehouse_name ILIKE \'SAPL-WH2\' AND gi.bill_date BETWEEN b.inspection_date AND a.planned_date_south THEN gi.issue END, \', \') AS south_issues, LISTAGG(DISTINCT CASE WHEN gi.warehouse_name ILIKE \'SAPL-NORTH-TAURU\' AND gi.bill_date BETWEEN b.inspection_date AND a.planned_date_north THEN gi.issue END, \', \') AS north_issues, CASE WHEN a.planned_date_north IS NULL OR a.actual_delivered_date_north IS NULL THEN NULL WHEN ( DATEDIFF(day, a.planned_date_north, a.actual_delivered_date_north) - CASE b.vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END ) <= 0 THEN 0.6 ELSE 0 END AS north_tat_points, CASE WHEN a.planned_date_south IS NULL OR a.actual_delivered_date_south IS NULL THEN NULL WHEN ( DATEDIFF(day, a.planned_date_south, a.actual_delivered_date_south) - CASE b.vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END ) <= 0 THEN 0.6 ELSE 0 END AS south_tat_points, CASE WHEN a.planned_date_north IS NULL THEN NULL WHEN COALESCE(TRIM(north_issues), \'\') = \'\' THEN 0.4 ELSE 0 END AS north_issue_points, CASE WHEN a.planned_date_south IS NULL THEN NULL WHEN COALESCE(TRIM(south_issues), \'\') = \'\' THEN 0.4 ELSE 0 END AS south_issue_points, FROM base b LEFT JOIN ALLOCATED a ON a.sku_group = b.sku_group LEFT JOIN planned_month pm ON pm.cleaned_sku = b.sku_group LEFT JOIN po_ranked pr ON b.sku_group = pr.sku_group AND pr.south_po_rn = 1 AND pr.north_po_rn = 1 LEFT JOIN grn_issues gi ON gi.sku_group = b.sku_group GROUP BY ALL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            